Clase Cuenta
    Privado Definir saldo Como Entero;

    Metodo Constructor(unSaldo Como Entero)
        Este.saldo <- unSaldo;
    FinMetodo

    Publico Metodo Saldo() Como Entero
        Retornar Este.saldo;
    FinMetodo

    Publico Metodo Depositar(monto Como Entero)
        Este.saldo <- Este.saldo + monto;
    FinMetodo
FinClase

Clase CuentaAhorro Hereda De Cuenta
    Privado Definir tasa Como Entero;

    Metodo Constructor(unSaldo Como Entero, unaTasa Como Entero)
        Super.Constructor(unSaldo);
        Este.tasa <- unaTasa;
    FinMetodo

    Publico Metodo AplicarInteres()
        Este.Depositar(Este.Saldo() * Este.tasa Div 100);
    FinMetodo
FinClase

Proceso EjecutarInteres
    Definir saldo Como Entero;
    Definir tasa Como Entero;
    Definir cuenta Como CuentaAhorro;
    Leer saldo;
    Leer tasa;
    cuenta <- Nuevo CuentaAhorro(saldo, tasa);
    cuenta.AplicarInteres();
    Escribir cuenta.Saldo();
FinProceso
